# WazobiaVoice TTS on Kaggle T4 - render a Short's narration lines in yo/ha/ig with ngozi, one subprocess worker per language (generated by muse-shorts scripts/export_lines.py). Settings: Accelerator = GPU T4 x1, Internet = On.
# Dataset "wazobia-bundle" attached (mounted under /kaggle/input/). No HF token needed.
import os, sys, glob, subprocess, zipfile, json, time, functools, shutil, faulthandler
faulthandler.dump_traceback_later(90, repeat=True, file=sys.stdout)

try: sys.stdout.reconfigure(line_buffering=True)
except Exception: pass
os.environ["HF_HUB_OFFLINE"] = "1"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "s3tokenizer", "einops", "omegaconf",
                "resemble-perth", "conformer==0.3.2", "pyloudnorm", "diffusers>=0.27", "loguru",
                "librosa>=0.10", "soundfile", "safetensors>=0.4.1", "onnxruntime"], check=True)


WORKER = r'''import os, sys, glob, subprocess, zipfile, json, time, functools, shutil, faulthandler
faulthandler.enable(file=sys.stderr, all_threads=True)
faulthandler.dump_traceback_later(90, repeat=True, file=sys.stderr)
try: sys.stdout.reconfigure(line_buffering=True)
except Exception: pass
os.environ["HF_HUB_OFFLINE"] = "1"
LID = sys.argv[1]
# locate bundle: auto-extracted folder or raw zip
root = None
for c in glob.glob("/kaggle/input/**/merged_model/s3gen.pt", recursive=True):
    root = os.path.dirname(os.path.dirname(c)); break
if root is None:
    z = glob.glob("/kaggle/input/**/*.zip", recursive=True)
    assert z, "bundle not found under /kaggle/input"
    zipfile.ZipFile(z[0]).extractall("/kaggle/tmp_bundle")
    root = os.path.dirname(os.path.dirname(glob.glob("/kaggle/tmp_bundle/**/merged_model/s3gen.pt", recursive=True)[0]))
base = os.path.dirname(root) if not os.path.isdir(os.path.join(root, "wazobiavoice_tts")) else root
pkg = glob.glob(os.path.join(os.path.dirname(root), "**/wazobiavoice_tts/__init__.py"), recursive=True) \
   or glob.glob("/kaggle/input/**/wazobiavoice_tts/__init__.py", recursive=True) \
   or glob.glob("/kaggle/tmp_bundle/**/wazobiavoice_tts/__init__.py", recursive=True)
src_dir = os.path.dirname(os.path.dirname(pkg[0]))
sys.path.insert(0, src_dir)
def find(name):
    return (glob.glob(f"/kaggle/input/**/{name}", recursive=True) + glob.glob(f"/kaggle/tmp_bundle/**/{name}", recursive=True))[0]
print("model root:", root, "| src:", src_dir)

import torch, numpy as np, soundfile as sf
import perth
if getattr(perth, "PerthImplicitWatermarker", None) is None:
    perth.PerthImplicitWatermarker = perth.DummyWatermarker
import importlib.metadata as _im
_orig_version=_im.version
def _safe_version(n):
    try: return _orig_version(n)
    except _im.PackageNotFoundError: return "0.0.0"
_im.version=_safe_version
try:
    import importlib_metadata as _im2; _im2.version=_safe_version
except Exception: pass
from wazobiavoice_tts.mtl_tts import WazobiaVoiceMultilingualTTS
assert torch.cuda.is_available(), "Turn on GPU T4 accelerator"
GPU = torch.cuda.get_device_name(0)
t = time.time()
# ROOT CAUSE of the hang: safetensors load_file / torch.load mmap the 2 GB + 1 GB files lazily, so the real
# reads happen as millions of random page faults inside load_state_dict on the slow /kaggle/input FUSE mount.
# Fix: sequentially copy the weights to local disk first, then load from there (local load ~7 s).
src_mm = os.path.join(root, "merged_model")
LOCAL = "/kaggle/tmp/merged_model" if os.access("/kaggle", os.W_OK) else "/tmp/merged_model"
os.makedirs(LOCAL, exist_ok=True)
for fn in sorted(os.listdir(src_mm)):
    s_, d_ = os.path.join(src_mm, fn), os.path.join(LOCAL, fn)
    if os.path.isfile(s_) and not (os.path.exists(d_) and os.path.getsize(d_) == os.path.getsize(s_)):
        tc = time.time()
        with open(s_, "rb") as fi, open(d_, "wb") as fo: shutil.copyfileobj(fi, fo, 64 * 1024 * 1024)
        dt = time.time() - tc; mb = os.path.getsize(d_) / 1e6
        print(f"copied {fn}: {mb:.0f} MB in {dt:.1f}s ({mb / max(dt, 1e-3):.0f} MB/s)")
print("weights on local disk:", LOCAL)

from pathlib import Path
from safetensors.torch import load_file as _st_load
from wazobiavoice_tts.mtl_tts import VoiceEncoder, T3, T3Config, S3Gen, MTLTokenizer, Conditionals
def tic(msg, t0): print(f"  {msg}: {time.time() - t0:.1f}s")
def load_model(ckpt, device="cuda"):
    ckpt = Path(ckpt)
    t0 = time.time(); ve = VoiceEncoder(); ve.load_state_dict(torch.load(ckpt / "ve.pt", map_location="cpu", weights_only=True)); ve.to(device).eval(); tic("ve", t0)
    t0 = time.time(); t3 = T3(T3Config.multilingual()); tic("t3 init", t0)
    t0 = time.time(); sd = _st_load(str(ckpt / "t3_mtl23ls_v2.safetensors"), device="cpu")
    if "model" in sd.keys(): sd = sd["model"][0]
    t3.load_state_dict(sd); del sd; t3.to(device).eval(); tic("t3 weights", t0)
    t0 = time.time(); s3 = S3Gen(); tic("s3gen init", t0)
    t0 = time.time(); sd = torch.load(ckpt / "s3gen.pt", map_location="cpu", weights_only=True, mmap=True)
    s3.load_state_dict(sd); del sd; s3.to(device).eval(); tic("s3gen weights", t0)
    tok = MTLTokenizer(str(ckpt / "grapheme_mtl_merged_expanded_v1.json"))
    conds = Conditionals.load(ckpt / "conds.pt", map_location="cpu").to(device) if (ckpt / "conds.pt").exists() else None
    return WazobiaVoiceMultilingualTTS(t3, s3, ve, tok, device, conds=conds)

t = time.time()
print("import ok; gpu", GPU, "- loading model"); model = load_model(LOCAL, "cuda")
print("loaded in", round(time.time() - t, 1), "s on", GPU)

TOKENS_PER_SEC, CHARS_PER_SEC = 25, 13
def token_cap(text):
    expected = max(1.5, len(text) / CHARS_PER_SEC) * TOKENS_PER_SEC
    return int(min(1000, int(1.3 * expected) + 40))

orig_inf = model.t3.inference
state = {"cap": 1000, "tokens": None}
@functools.wraps(orig_inf)
def capped(*a, **kw):
    kw["max_new_tokens"] = state["cap"]
    r = orig_inf(*a, **kw)
    state["tokens"] = int(r.shape[-1])
    return r
model.t3.inference = capped

import pyloudnorm as pyln
def trim_norm(a, sr, thr_db=-50.0, pad=0.3, target_lufs=-16.0):
    win = max(1, int(sr * 0.02)); n = len(a) // win
    if n:
        rms = np.sqrt(np.mean(a[:n * win].reshape(n, win) ** 2, axis=1) + 1e-12)
        loud = np.where(20 * np.log10(rms) > thr_db)[0]
        if len(loud):
            p = int(pad * sr)
            a = a[max(0, loud[0] * win - p): min(len(a), (loud[-1] + 1) * win + p)]
    try:
        m = pyln.Meter(sr); l = m.integrated_loudness(a)
        if np.isfinite(l): a = pyln.normalize.loudness(a, l, target_lufs)
    except Exception as e: print("loudnorm skipped:", e)
    pk = np.max(np.abs(a)) if len(a) else 0
    if pk > 0.99: a = a * (0.99 / pk)
    return a.astype("float32")

import hashlib, re, unicodedata, random
LINES = json.load(open("/kaggle/working/lines.json", encoding="utf-8"))[LID]
VOICE, SEED, PAUSE = "ngozi", 1234, 0.18
def text_hash(t):
    t = re.sub(r"\s+", " ", unicodedata.normalize("NFC", t or "").strip())
    return hashlib.sha1(t.encode("utf-8")).hexdigest()[:16]
def seed_all(s):
    random.seed(s); np.random.seed(s); torch.manual_seed(s); torch.cuda.manual_seed_all(s)
def sentences(t):
    parts = [p.strip() for p in re.split(r"(?<=[.!?])\s+", t) if p.strip()]
    return parts or [t]

OUT = f"/kaggle/working/out/{LID}"
os.makedirs(OUT, exist_ok=True)
model.prepare_conditionals(find(f"inbuilt_voices/{VOICE}.wav"), exaggeration=0.5)
manifest = {"voice": VOICE, "seed": SEED, "gpu": GPU, "sr": int(model.sr), "lufs": -16.0, "lang": LID, "lines": []}
for L in LINES:
    assert text_hash(L["text"]) == L["hash"], f"hash mismatch line {L['index']}"
    pieces, segs = [], []
    for k, sent in enumerate(sentences(L["text"])):
        seed_all(SEED + 1000 * L["index"] + k)
        state["cap"] = token_cap(sent); torch.cuda.synchronize(); ts = time.time()
        wav = model.generate(sent, language_id=LID, exaggeration=0.5, cfg_weight=0.5, temperature=0.7)
        torch.cuda.synchronize(); g = time.time() - ts
        raw = wav.squeeze().detach().cpu().numpy().astype("float32")
        a = trim_norm(raw, model.sr, pad=0.12)
        if pieces: pieces.append(np.zeros(int(PAUSE * model.sr), dtype="float32"))
        pieces.append(a)
        segs.append({"text": sent, "gpu_s": round(g, 2), "tokens": state["tokens"], "cap": state["cap"],
                     "cap_hit": state["tokens"] is not None and state["tokens"] >= state["cap"] - 1,
                     "raw_s": round(len(raw) / model.sr, 2), "trimmed_s": round(len(a) / model.sr, 2)})
    a = trim_norm(np.concatenate(pieces), model.sr, pad=0.15)
    fn = f"{L['index']:02}_{L['hash']}.wav"; sf.write(f"{OUT}/{fn}", a, model.sr)
    row = {"index": L["index"], "lang": LID, "voice": VOICE, "hash": L["hash"], "text": L["text"], "file": fn,
           "seconds": round(len(a) / model.sr, 2), "segments": segs}
    manifest["lines"].append(row)
    json.dump(manifest, open(f"{OUT}/runs.json", "w", encoding="utf-8"), indent=2, ensure_ascii=False)   # partial results survive a crash
    print("LINE", json.dumps({k: row[k] for k in ("index", "file", "seconds")} | {"cap_hits": sum(x["cap_hit"] for x in segs)}), flush=True)
print("RESULT", LID, len(manifest["lines"]), "lines", flush=True)
'''
os.makedirs("/kaggle/working", exist_ok=True)
LINES_JSON = None  # filled by scripts/export_lines.py
LINES_BY_LANG = json.loads(LINES_JSON)
json.dump(LINES_BY_LANG, open("/kaggle/working/lines.json", "w", encoding="utf-8"), ensure_ascii=False)
open("/kaggle/working/worker.py", "w", encoding="utf-8").write(WORKER)
faulthandler.cancel_dump_traceback_later()
import collections
OUT = "/kaggle/working/out"
if os.path.isdir(OUT): shutil.rmtree(OUT)
os.makedirs(OUT)
manifest = {"voice": "ngozi", "kind": "lines-by-lang", "runs": []}
def mem_report(tag):
    try:
        out = subprocess.run(["nvidia-smi", "--query-gpu=memory.used,memory.total", "--format=csv,noheader"], capture_output=True, text=True).stdout.strip()
    except Exception as e: out = repr(e)
    try:
        import psutil; vm = psutil.virtual_memory(); ram = f"free RAM {vm.available // 2**20} MB / {vm.total // 2**20} MB"
    except Exception: ram = subprocess.run(["free", "-m"], capture_output=True, text=True).stdout
    try:
        import torch; cm = f"torch.cuda alloc {torch.cuda.memory_allocated() // 2**20} MB reserved {torch.cuda.memory_reserved() // 2**20} MB" if torch.cuda.is_available() else "no cuda"
    except Exception as e: cm = repr(e)
    s = f"[{tag}] GPU(nvidia-smi used,total): {out} | {cm} | {ram}"
    print(s, flush=True); print(subprocess.run(["free", "-m"], capture_output=True, text=True).stdout, flush=True); return s
T0 = time.time()
try:
    for lid in LINES_BY_LANG:
        rec = {"lang": lid, "mem_before": mem_report(lid)}
        ts = time.time(); tail = collections.deque(maxlen=40)
        env = dict(os.environ, PYTHONUNBUFFERED="1", PYTHONIOENCODING="utf-8")
        try:
            p = subprocess.Popen([sys.executable, "-u", "/kaggle/working/worker.py", lid], stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                 text=True, encoding="utf-8", errors="replace", bufsize=1, env=env)
            for line in p.stdout:
                print(f"[{lid}] " + line, end="", flush=True); tail.append(line.rstrip("\n"))
            rec["returncode"] = p.wait()
        except Exception as e:
            rec["returncode"] = None; rec["error"] = repr(e)[:300]
        rec["wall_s"] = round(time.time() - ts, 1); rec["tail"] = list(tail)
        jp = f"{OUT}/{lid}/manifest.json"
        done = len(json.load(open(jp, encoding="utf-8"))["lines"]) if os.path.exists(jp) else 0
        rec["lines_done"], rec["lines_expected"] = done, len(LINES_BY_LANG[lid])
        rec["ok"] = rec.get("returncode") == 0 and done == len(LINES_BY_LANG[lid])
        manifest["runs"].append(rec)
        print(f"== {lid}: rc={rec.get('returncode')} ok={rec['ok']} in {rec['wall_s']}s", flush=True)
finally:
    manifest["total_s"] = round(time.time() - T0, 1)
    try: json.dump(manifest, open(f"{OUT}/runs.json", "w", encoding="utf-8"), indent=2, ensure_ascii=False)
    except Exception as e: print("manifest write failed:", e)
    try:
        if os.path.exists("/kaggle/working/wz_out.zip"): os.remove("/kaggle/working/wz_out.zip")
        shutil.make_archive("/kaggle/working/wz_out", "zip", OUT)
        print("DONE ->", [ (r["lang"], r["ok"]) for r in manifest["runs"] ], "/kaggle/working/wz_out.zip", os.path.getsize("/kaggle/working/wz_out.zip") // 1024, "KB", flush=True)
    except Exception as e: print("zip failed:", e)
